  let total=0;const cum=[0];
  for(let i=0;i<dense.length-1;i++){total+=Math.hypot(dense[i+1].x-dense[i].x,dense[i+1].y-dense[i].y);cum.push(total);}
  const N=Math.max(8,Math.round(total/step)),out=[];
